const unwrap = value => {
  if (Array.isArray(value)) value = value[0];
  if (value && typeof value === 'object') value = value.value ?? value.name ?? value.id;
  return value === undefined || value === null ? '' : String(value).trim();
};
return $input.all().map((item, index) => {
  const row = item.json;
  const recordId = unwrap(row.id ?? row.recordId);
  const campaignId = Number(unwrap(row.ID ?? row['EmailBison Campaign ID']));
  const campaignName = unwrap(row.Name ?? row['Campaign Name']);
  const apiKey = unwrap(row['EmailBison API (from Client)'] ?? row['EmailBison API']);
  if (!recordId.startsWith('rec')) throw new Error('Airtable Campaign record ID is missing.');
  if (!Number.isFinite(campaignId) || campaignId <= 0) throw new Error('Campaign ' + campaignName + ' has no numeric EmailBison campaign ID.');
  if (!apiKey) throw new Error('Campaign ' + campaignName + ' has no EmailBison API key lookup value.');
  return {json: {recordId, campaignId, campaignName, apiKey, baseUrl: 'https://send.dulcy.io'}, pairedItem: {item: index}};
});

const buildCampaignRows = (campaign, sequenceResponse, reportingResponse) => {

const firstArray = value => {
  if (Array.isArray(value)) return value;
  if (!value || typeof value !== 'object') return [];
  for (const key of ['sequence_steps', 'steps', 'items', 'results']) {
    if (Array.isArray(value[key])) return value[key];
  }
  if (value.data !== undefined) return firstArray(value.data);
  return [];
};
const steps = firstArray(sequenceResponse);
if (!steps.length) throw new Error('EmailBison returned no sequence steps for campaign ' + campaign.campaignId + '. No Airtable rows were written.');

const numberFrom = (object, aliases) => {
  for (const key of aliases) {
    if (object && object[key] !== undefined && object[key] !== null && object[key] !== '') {
      const value = Number(object[key]);
      if (Number.isFinite(value)) return value;
    }
  }
  return undefined;
};
const aliases = {
  sent: ['emails_sent', 'sent_emails', 'sent_count', 'total_sent', 'sent'],
  delivered: ['emails_delivered', 'delivered_count', 'total_delivered', 'delivered'],
  replies: ['unique_replies', 'reply_count', 'total_replies', 'replies'],
  interested: ['interested_replies', 'positive_replies', 'interested_count', 'interested'],
  meetings: ['meetings_booked', 'meeting_count', 'meetings'],
  bounces: ['bounced', 'bounce_count', 'total_bounces', 'bounces']
};
const metricObjects = [];
const walk = (value, path = '') => {
  if (Array.isArray(value)) {
    value.forEach((item, index) => walk(item, path + '[' + index + ']'));
    return;
  }
  if (!value || typeof value !== 'object') return;
  const metrics = {};
  for (const [name, keys] of Object.entries(aliases)) metrics[name] = numberFrom(value, keys);
  if (Object.values(metrics).some(item => item !== undefined)) metricObjects.push({value, metrics, path});
  for (const [key, item] of Object.entries(value)) walk(item, path ? path + '.' + key : key);
};
walk(reportingResponse);

const stepIdOf = object => numberFrom(object, ['sequence_step_id', 'sequenceStepId', 'step_id', 'stepId']);
const orderOf = object => numberFrom(object, ['step_number', 'stepNumber', 'step_order', 'stepOrder', 'order', 'step']);
const variantText = object => {
  const raw = object?.variant_label ?? object?.variantLabel ?? object?.variant_name ?? object?.variantName;
  return raw === undefined || raw === null ? '' : String(raw).trim().toUpperCase();
};
const stepById = new Map(steps.map(step => [Number(step.id ?? step.sequence_step_id), step]));
const effectiveOrder = step => {
  const direct = Number(step.order ?? step.step ?? step.step_number);
  if (Number.isFinite(direct) && direct > 0) return direct;
  const parentId = Number(step.variant_from_step_id ?? step.variantFromStepId ?? step.variant_from_step ?? step.variantFromStep ?? step.parent_step_id ?? step.parentStepId);
  const parent = stepById.get(parentId);
  const inherited = Number(parent?.order ?? parent?.step ?? parent?.step_number);
  return Number.isFinite(inherited) && inherited > 0 ? inherited : 0;
};
const labelByStepId = new Map();
const orders = [...new Set(steps.map(effectiveOrder))];
for (const order of orders) {
  const group = steps.filter(step => effectiveOrder(step) === order);
  const referencedIds = new Set(group.map(step => Number(step.variant_from_step_id ?? step.variantFromStepId ?? step.variant_from_step ?? step.variantFromStep ?? step.parent_step_id ?? step.parentStepId)).filter(Number.isFinite));
  const primary = group.find(step => referencedIds.has(Number(step.id ?? step.sequence_step_id)))
    ?? group.find(step => !step.variant && !Number(step.variant_from_step_id ?? step.variantFromStepId ?? step.variant_from_step ?? step.variantFromStep ?? step.parent_step_id ?? step.parentStepId))
    ?? [...group].sort((a, b) => Number(a.id ?? a.sequence_step_id) - Number(b.id ?? b.sequence_step_id))[0];
  const ordered = [primary, ...group.filter(step => step !== primary).sort((a, b) => Number(a.id ?? a.sequence_step_id) - Number(b.id ?? b.sequence_step_id))].filter(Boolean);
  ordered.forEach((step, index) => labelByStepId.set(Number(step.id ?? step.sequence_step_id), String.fromCharCode(65 + Math.min(index, 9))));
}
const plainText = value => String(value ?? '')
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<\/p\s*>/gi, '\n\n')
  .replace(/<\/div\s*>/gi, '\n')
  .replace(/<li[^>]*>/gi, '- ')
  .replace(/<[^>]+>/g, '')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>')
  .replace(/&quot;/gi, '"')
  .replace(/&#39;|&apos;/gi, "'")
  .replace(/[ \t]+\n/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();
const date = new Date().toLocaleDateString('en-CA', {timeZone: 'America/New_York'});
const now = new Date().toISOString();
const rows = [];
const unmatched = [];
for (const step of steps) {
  const stepId = Number(step.id ?? step.sequence_step_id);
  const stepNumber = effectiveOrder(step);
  const variant = labelByStepId.get(stepId) ?? 'A';
  const matches = metricObjects.filter(entry => {
    const metricStepId = stepIdOf(entry.value);
    const metricOrder = orderOf(entry.value);
    const metricVariant = variantText(entry.value);
    if (metricStepId !== undefined) return metricStepId === stepId;
    if (metricOrder !== undefined && metricOrder !== stepNumber) return false;
    if (metricVariant) return metricVariant === variant;
    return metricOrder !== undefined;
  });
  if (!matches.length) { unmatched.push('Step ' + stepNumber + ' Variant ' + variant + ' (ID ' + stepId + ')'); continue; }
  const totals = {sent: 0, delivered: 0, replies: 0, interested: 0, meetings: 0, bounces: 0};
  for (const match of matches) {
    for (const key of Object.keys(totals)) if (match.metrics[key] !== undefined) totals[key] += match.metrics[key];
  }
  rows.push({json: {
    'Sequence Metric Key': campaign.campaignId + '-total-' + stepId,
    'Campaign': [campaign.recordId],
    'Campaign ID': campaign.campaignId,
    'Date': date,
    'Sequence Step ID': stepId,
    'Step Number': stepNumber,
    'Variant': variant,
    'Subject': plainText(step.email_subject ?? step.subject ?? ''),
    'Email Copy Snapshot': plainText(step.email_body ?? step.body ?? ''),
    'Emails Sent': totals.sent,
    'Replies': totals.replies,
    'Interested Replies': totals.interested,
    'Bounces': totals.bounces,
    'Last Synced': now
  }});
}
if (!rows.length) {
  const paths = metricObjects.slice(0, 10).map(item => item.path || '(root)').join(', ') || 'none';
  throw new Error('EmailBison reporting returned no metrics attributable to a sequence step or variant for campaign ' + campaign.campaignId + '. Metric-bearing response paths: ' + paths + '. No Airtable rows were written. Inspect this node input and map the returned step identifier before enabling the schedule.');
}
if (unmatched.length) throw new Error('EmailBison returned incomplete step attribution for campaign ' + campaign.campaignId + ': ' + unmatched.join(', ') + '. No partial Airtable data was written.');
return rows;
};

const campaigns = $('Normalize Campaign').all();
const sequenceResponses = $('Get Sequence Steps').all();
const reportingResponses = $input.all();
if (campaigns.length !== reportingResponses.length || sequenceResponses.length !== reportingResponses.length) {
  throw new Error('Campaign, sequence, and reporting item counts do not match. Campaigns: ' + campaigns.length + ', sequences: ' + sequenceResponses.length + ', reports: ' + reportingResponses.length + '.');
}
const outputRows = [];
const failures = [];
for (let index = 0; index < reportingResponses.length; index++) {
  try {
    outputRows.push(...buildCampaignRows(campaigns[index].json, sequenceResponses[index].json, reportingResponses[index].json));
  } catch (error) {
    const campaignName = campaigns[index]?.json?.campaignName ?? ('item ' + index);
    failures.push(campaignName + ': ' + (error?.message ?? String(error)));
  }
}
if (failures.length) console.log('Sequence analytics skipped campaigns: ' + failures.join(' | '));
if (!outputRows.length) throw new Error('No sequence analytics rows were produced. ' + failures.join(' | '));
return outputRows;
